using System.Buffers.Binary;
using System.Text.Json;
using Cozmo.Robot;
using Cozmo.Robot.Behavior;
using Cozmo.Robot.Vision.Jpeg;
using Xunit;

namespace Cozmo.Protocol.Tests;

[Collection("SteppedBehavior missing-report statics")]
public class ImdecodeDispatchTests
{
    [Fact]
    public void WebP_ProbeMatchesShippedNativeOracle()
    {
        // Expected statuses are the shipped ARM code's results, generated by gen_imdecode_dispatch_fixtures.py.
        using var fixture = JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,
            "Fixtures", "imdecode_dispatch", "webp-probe.json")));
        foreach (var c in fixture.RootElement.GetProperty("cases").EnumerateArray())
        {
            byte[]? b = c.GetProperty("data_present").GetBoolean() ? Convert.FromHexString(c.GetProperty("window_hex").GetString()!) : null;
            int actual = OpenCvImage.WebPProbe(b, c.GetProperty("version").GetInt32(), c.GetProperty("features_present").GetBoolean());
            Assert.True(actual == c.GetProperty("status").GetInt32(), c.GetProperty("id").GetString());
        }
    }

    // A.2 signatures, corrected by C.1: all checks see a 32-byte space-padded window.
    [Theory]
    [InlineData("424D", "BMP")]
    [InlineData("233F52474245", "HDR")]
    [InlineData("233F52414449414E4345", "HDR")]
    [InlineData("2F", "WebP")]
    [InlineData("59A66A95", "SunRaster")]
    [InlineData("5035", "PxM")]
    [InlineData("503609", "PxM")]
    [InlineData("49492A00", "TIFF")]
    [InlineData("4D4D002A", "TIFF")]
    [InlineData("89504E470D0A1A0A", "PNG")]
    [InlineData("0000000C6A5020200D0A870A", "JPEG2000")]
    [InlineData("762F3101", "EXR")]
    public void PaddedWindowRoutesToMatchedUnportedDecoder(string hex, string decoder)
    {
        Assert.Equal(new[] { $"MISSING: M3-045 | {decoder} signature matched: decoder body is not ported" },
            Capture(() => Assert.True(OpenCvImage.Imdecode(Convert.FromHexString(hex), 0).IsEmpty)));
    }

    [Theory]
    [InlineData("FFD8FF")]
    [InlineData("524946460000000057454250")]
    [InlineData("5037FF")]
    [InlineData("5031FF")]
    [InlineData("503100")]
    [InlineData("00")]
    public void FailedJpegAndNoMatchGiveSilentEmpty(string hex)
    {
        Assert.Empty(Capture(() => Assert.True(OpenCvImage.Imdecode(Convert.FromHexString(hex), 0).IsEmpty)));
    }

    [Theory]
    [InlineData(8)]
    [InlineData(31)]
    [InlineData(32)]
    [InlineData(33)]
    public void WebPRejectsPngAndDispatchContinuesAtEveryPayloadLength(int size)
    {
        var payload = new byte[size];
        Convert.FromHexString("89504E470D0A1A0A").CopyTo(payload, 0);
        Assert.Equal(new[] { "MISSING: M3-045 | PNG signature matched: decoder body is not ported" },
            Capture(() => Assert.True(OpenCvImage.Imdecode(payload, 0).IsEmpty)));
    }

    [Theory]
    [InlineData(1)]
    [InlineData(31)]
    [InlineData(32)]
    [InlineData(33)]
    public void SpacePaddingMakesShortRawLosslessWebPMatch(int size)
    {
        var payload = new byte[size];
        payload[0] = 0x2F; // C.1/C.3 P11: remaining bits, including version, are unchecked.
        Assert.Equal(new[] { "MISSING: M3-045 | WebP signature matched: decoder body is not ported" },
            Capture(() => Assert.True(OpenCvImage.Imdecode(payload, 0).IsEmpty)));
    }

    [Fact]
    public void LongJpegWindowKeepsExistingDecoder()
    {
        var payload = new byte[40];
        Convert.FromHexString("FFD8FF").CopyTo(payload, 0);
        Assert.Empty(Capture(() => Assert.True(OpenCvImage.Imdecode(payload, 0).IsEmpty)));
        // Valid long JPEG decode and pixels remain covered by JpegDecodeOracleTests' shipped-library fixtures.
    }

    [Theory]
    [InlineData(8)]
    [InlineData(32)]
    public void CameraChunkEntryReachesSignatureDispatch(int size)
    {
        var payload = new byte[size];
        Convert.FromHexString("89504E470D0A1A0A").CopyTo(payload, 0);
        var camera = new CozmoCamera();
        CameraFrame? frame = null;
        camera.FrameReceived += f => frame = f;
        camera.Handle(new ImageChunk { ImageId = 1, ChunkId = 0, ImageChunkCount = 1,
            ImageEncoding = 5, ImageResolution = 4, Data = payload });
        Assert.NotNull(frame);
        Assert.Equal(new[] { "MISSING: M3-045 | PNG signature matched: decoder body is not ported" },
            Capture(() => Assert.False(EncodedImageDecoder.TryDecodeGray(frame!, out _, out _))));
    }

    // P4/P6: RIFF size is not compared against the window; flags/later chunks don't affect VP8X success.
    [Fact]
    public void WebP_RiffExtendedHeaderAcceptsLargeRiffAndUncheckedFlags()
    {
        var b = Riff("VP8X", 10, 0xFFFFFFF6u);
        Put(b, 20, uint.MaxValue);
        Assert.Equal(0, OpenCvImage.WebPProbe(b, 0x201));
        Assert.Equal(new[] { "MISSING: M3-045 | WebP signature matched: decoder body is not ported" },
            Capture(() => Assert.True(OpenCvImage.Imdecode(b, 1).IsEmpty)));
    }

    // P9/P11/P12/P13: each raw, RIFF, bare chunk and optional-ALPH route to the bitstream.
    [Theory]
    [InlineData("raw", true)]
    [InlineData("riff", true)]
    [InlineData("chunk", true)]
    [InlineData("alph", true)]
    [InlineData("raw", false)]
    [InlineData("riff", false)]
    [InlineData("chunk", false)]
    [InlineData("alph", false)]
    public void WebP_EachBitstreamAcceptanceShape(string route, bool lossless)
    {
        var b = Bitstream(route, lossless);
        Assert.Equal(0, OpenCvImage.WebPProbe(b, 0x201));
        Assert.Equal(new[] { "MISSING: M3-045 | WebP signature matched: decoder body is not ported" },
            Capture(() => Assert.True(OpenCvImage.Imdecode(b, 0).IsEmpty)));
    }

    // C.3: explicit status branches reachable with a 32-byte input. Expected statuses are from the rows.
    [Theory]
    [InlineData("riff-not-webp", 3)]
    [InlineData("riff-too-small", 3)]
    [InlineData("riff-too-large", 3)]
    [InlineData("vp8x-size", 3)]
    [InlineData("vp8x-product", 3)]
    [InlineData("vp8x-no-riff", 3)]
    [InlineData("alph-cap", 3)]
    [InlineData("alph-incomplete-chunk", 7)]
    [InlineData("alph-next-header-too-short", 7)]
    [InlineData("riff-chunk-exceeds-riff", 3)]
    [InlineData("bitstream-size-cap", 3)]
    [InlineData("lossless-too-short", 7)]
    [InlineData("lossless-marker", 3)]
    [InlineData("lossy-too-short", 7)]
    [InlineData("lossy-key-marker", 3)]
    [InlineData("lossy-not-key-frame", 3)]
    [InlineData("lossy-version", 3)]
    [InlineData("lossy-not-shown", 3)]
    [InlineData("lossy-partition-equal-size", 3)]
    public void WebP_EachReachableErrorBranchRejectsAndDispatchContinues(string branch, int expected)
    {
        byte[] b = branch switch
        {
            "riff-not-webp" or "riff-too-small" or "riff-too-large" or "riff-chunk-exceeds-riff" => Riff("VP8L", 5, 20),
            "vp8x-size" or "vp8x-product" => Riff("VP8X", 10, 22),
            "vp8x-no-riff" => Chunk("VP8X", 10),
            "alph-cap" or "alph-incomplete-chunk" or "alph-next-header-too-short" or "lossless-too-short" or "lossy-too-short" => Chunk("ALPH", 0),
            "bitstream-size-cap" or "lossless-marker" => Bitstream("chunk", true),
            _ => Bitstream("raw", false),
        };
        switch (branch)
        {
            case "riff-not-webp": b[8] = 0; break;
            case "riff-too-small": Put(b, 4, 11); break;
            case "riff-too-large": Put(b, 4, 0xFFFFFFF7u); break;
            case "vp8x-size": Put(b, 16, 9); break;
            case "vp8x-product": Array.Fill(b, (byte)0xFF, 24, 6); break;
            case "alph-cap": Put(b, 4, 0xFFFFFFF7u); break;
            case "alph-incomplete-chunk": Put(b, 4, 25); break;
            case "alph-next-header-too-short": Put(b, 4, 17); break; // d=26 leaves n=6
            case "riff-chunk-exceeds-riff": Put(b, 16, 9); break; // cs=9 > riff-12=8
            case "bitstream-size-cap": Put(b, 4, 0xFFFFFFF7u); break;
            case "lossless-too-short": Put(b, 4, 12); SetTag(b, 20, "VP8L"); break; // n=4 after header
            case "lossless-marker": b[8] = 0; break;
            case "lossy-too-short": Put(b, 4, 8); SetTag(b, 16, "VP8 "); break; // n=8 after header
            case "lossy-key-marker": b[3] = 0; break;
            case "lossy-not-key-frame": b[0] = 0x11; break;
            case "lossy-version": b[0] = 0x18; break;
            case "lossy-not-shown": b[0] = 0; break;
            case "lossy-partition-equal-size": b[1] = 4; break; // bits=0x410; bits>>5=32 == cs
        }
        Assert.Equal(expected, OpenCvImage.WebPProbe(b, 0x201));
        Assert.Empty(Capture(() => Assert.True(OpenCvImage.Imdecode(b, 0).IsEmpty)));
    }

    [Fact]
    public void WebP_VersionAndNullGuardsUseArithmeticShift()
    {
        var b = Bitstream("raw", true);
        Assert.Equal(0, OpenCvImage.WebPProbe(b, 0x200));
        Assert.Equal(0, OpenCvImage.WebPProbe(b, 0x2FF));
        Assert.Equal(2, OpenCvImage.WebPProbe(b, 0x300));
        Assert.Equal(2, OpenCvImage.WebPProbe(b, -1));
        Assert.Equal(2, OpenCvImage.WebPProbe(null, 0x201));
        Assert.Equal(2, OpenCvImage.WebPProbe(b, 0x201, featuresPresent: false));
    }

    private static byte[] Chunk(string tag, uint size)
    {
        var b = new byte[32];
        SetTag(b, 0, tag);
        Put(b, 4, size);
        return b;
    }
    private static byte[] Riff(string tag, uint size, uint riffSize)
    {
        var b = Chunk("RIFF", riffSize);
        SetTag(b, 8, "WEBP");
        SetTag(b, 12, tag);
        Put(b, 16, size);
        return b;
    }
    private static byte[] Bitstream(string route, bool lossless)
    {
        string tag = lossless ? "VP8L" : "VP8 ";
        byte[] b = route switch { "riff" => Riff(tag, 12, 24), "chunk" => Chunk(tag, 12), "alph" => Chunk("ALPH", 0), _ => new byte[32] };
        int p = route switch { "riff" => 20, "chunk" => 8, "alph" => 16, _ => 0 };
        if (route == "alph") { SetTag(b, 8, tag); Put(b, 12, 12); }
        if (lossless) b[p] = 0x2F;
        else { b[p] = 0x10; b[p + 3] = 0x9D; b[p + 4] = 1; b[p + 5] = 0x2A; } // zero dimensions accepted (P12)
        return b;
    }
    private static void SetTag(byte[] b, int p, string tag) => System.Text.Encoding.ASCII.GetBytes(tag).CopyTo(b, p);
    private static void Put(byte[] b, int p, uint value) => BinaryPrimitives.WriteUInt32LittleEndian(b.AsSpan(p, 4), value);

    private static List<string> Capture(Action action)
    {
        SteppedBehavior.ResetMissingForTests();
        var logs = new List<string>();
        void Receive(string line) { if (line.StartsWith("MISSING: M3-045 |")) logs.Add(line); }
        SteppedBehavior.MissingReported += Receive;
        try { action(); }
        finally { SteppedBehavior.MissingReported -= Receive; }
        return logs;
    }
}
